// Exact full-gamma fibre and affine audit for K21 compressed HIT streams.
// For kc>0, BOTH gamma orientations are explicitly scored; unlike c=0,
// gamma -> -gamma cannot be quotiented after fixing the compressed c sign.
// The negacyclic equation alpha gamma* - gamma alpha*=0 is solved by MITM.
// Every full cyclic-cross lift is scored under all 500 induced affine images
// against the exact K21 V budget qmin(G)+||V||^2<=57; any survivor is checked for odd-perfectness
// and full LABS energy.
#include <bits/stdc++.h>
#include <omp.h>
using namespace std;static const int N=25;using A=array<int,N>;using Vec=array<int16_t,N>;
struct VH{size_t operator()(Vec const&v)const noexcept{uint64_t h=1469598103934665603ULL;for(auto x:v){h^=(uint16_t)(x+64);h*=1099511628211ULL;}return h;}};
Vec comm(const A&a,const A&g){Vec f{};auto add=[&](int e,int v){if(e>=0)f[e]+=v;else f[e+N]-=v;};for(int i=0;i<N;i++)if(a[i])for(int j=0;j<N;j++)if(g[j]){add(i-j,a[i]*g[j]);add(j-i,-g[j]*a[i]);}return f;}
vector<uint32_t> solve_gamma(const A&alpha,const vector<int>&supp){int fix=supp[0];vector<int>v(supp.begin()+1,supp.end());int n1=v.size()/2,n2=v.size()-n1;array<Vec,N>col{};for(int j:supp){A e{};e[j]=1;col[j]=comm(alpha,e);}unordered_map<Vec,vector<uint16_t>,VH>mp;mp.reserve(1024);for(uint32_t m=0;m<(1u<<n1);m++){Vec z=col[fix];for(int t=0;t<n1;t++){int s=(m>>t&1)?1:-1;for(int r=0;r<N;r++)z[r]+=s*col[v[t]][r];}mp[z].push_back((uint16_t)m);}vector<uint32_t>sol;for(uint32_t m=0;m<(1u<<n2);m++){Vec z{};for(int t=0;t<n2;t++){int s=(m>>t&1)?1:-1;for(int r=0;r<N;r++)z[r]+=s*col[v[n1+t]][r];}for(auto&x:z)x=-x;auto it=mp.find(z);if(it==mp.end())continue;for(uint16_t lm:it->second){uint32_t mask=1u<<fix;for(int t=0;t<n1;t++)if(lm>>t&1)mask|=1u<<v[t];for(int t=0;t<n2;t++)if(m>>t&1)mask|=1u<<v[n1+t];sol.push_back(mask);}}return sol;}
A q_from_c(const A&c){A q{};for(int j=0;j<N;j++)q[j]=c[(j+13)%N];return q;}A beta_from_gamma(const A&g){A b{};for(int i=0;i<N;i++){int j=i-13;if(j>=0)b[j]=g[i];else b[j+N]=-g[i];}return b;}
inline uint64_t masklo(int n){return n?((1ULL<<n)-1):0ULL;}inline int corr(uint64_t x,int r){int n=50-r;return n-2*__builtin_popcountll((x^(x>>r))&masklo(n));}inline int xcorr(uint64_t x,uint64_t y,int r){int n=50-r;return n-2*__builtin_popcountll((x^(y>>r))&masklo(n));}inline uint64_t rot50(uint64_t x,int k){const uint64_t M=(1ULL<<50)-1;k%=50;if(!k)return x&M;return((x<<k)|(x>>(50-k)))&M;}uint64_t multperm(uint64_t x,int ah){uint64_t y=0;for(int i=0;i<50;i++)if(x>>i&1)y|=1ULL<<((ah*i)%50);return y;}inline int oddcorr(uint64_t A0,uint64_t B0,int r){return xcorr(A0,B0,r)+(r<49?xcorr(B0,A0,r+1):0);}bool cyclic0(uint64_t A0,uint64_t B0){for(int r=0;r<25;r++)if(oddcorr(A0,B0,r)+oddcorr(A0,B0,49-r)!=0)return false;return true;}
bool oddperfect(uint64_t A0,uint64_t B0){for(int r=0;r<50;r++)if(abs(oddcorr(A0,B0,r))!=1)return false;return true;}int energy(uint64_t A0,uint64_t B0){long long E=0;for(int r=1;r<50;r++){int c=corr(A0,r)+corr(B0,r);E+=1LL*c*c;}for(int r=0;r<50;r++){int c=oddcorr(A0,B0,r);E+=1LL*c*c;}return E;}
int qminG(const A&p,const A&c){int q=0;for(int r=1;r<=12;r++){int g=0;for(int i=0;i<N;i++)g+=p[i]*p[(i+r)%N]+c[i]*c[(i+r)%N];q+=(g*g+(abs(g)&1))/2;}return q;}
struct H{A p,c;int cap;};
int main(int argc,char**argv){if(argc<2)return 2;bool countonly=argc>2&&string(argv[2])=="--count-only";ifstream f(argv[1]);string line;vector<H>hs;while(getline(f,line)){if(line.rfind("HIT ",0))continue;auto a=line.find("p=")+2,b=line.find("|c=");string ps=line.substr(a,b-a),cs=line.substr(b+3);replace(ps.begin(),ps.end(),',',' ');replace(cs.begin(),cs.end(),',',' ');stringstream sp(ps),sc(cs);H h{};for(int&i:h.p)sp>>i;for(int&i:h.c)sc>>i;h.cap=57-qminG(h.p,h.c);if(h.cap<0)abort();hs.push_back(h);}cerr<<"REPS "<<hs.size()<<" capmax="<<max_element(hs.begin(),hs.end(),[](auto&a,auto&b){return a.cap<b.cap;})->cap<<"\n";if(hs.empty())return 3;vector<int>units;for(int a=0;a<N;a++)if(gcd(a,N)==1)units.push_back(a);
 atomic<long long>alphas{0},lifts{0},qpass{0},trans{0},vpass{0},opass{0},epass{0};atomic<int>best{INT_MAX};
int ZA=0;for(int i=0;i<25;i++)if(!hs[0].p[i])ZA++;int AC=1<<ZA;
#pragma omp parallel for schedule(dynamic,1)
 for(int task=0;task<(int)hs.size()*AC;task++){int hi=task/AC,am=task%AC;auto &H=hs[hi];vector<int>az,gs;for(int i=0;i<N;i++){if(!H.p[i])az.push_back(i);if(!H.c[i])gs.push_back(i);}if((int)az.size()!=ZA)abort();A alpha{};for(int t=0;t<ZA;t++)alpha[az[t]]=(am>>t&1)?1:-1;alphas++;auto G=solve_gamma(alpha,gs);lifts+=G.size();A q=q_from_c(H.c);if(countonly)continue;for(uint32_t gm:G)for(int gsign:{1,-1}){A gamma{};for(int j:gs)gamma[j]=gsign*((gm>>j&1)?1:-1);A beta=beta_from_gamma(gamma);uint64_t Ab=0,Bb=0;for(int i=0;i<N;i++){int A1=H.p[i]+alpha[i],A2=H.p[i]-alpha[i],B1=q[i]+beta[i],B2=q[i]-beta[i];if(abs(A1)!=1||abs(A2)!=1||abs(B1)!=1||abs(B2)!=1)abort();if(A1==1)Ab|=1ULL<<i;if(A2==1)Ab|=1ULL<<(i+25);if(B1==1)Bb|=1ULL<<i;if(B2==1)Bb|=1ULL<<(i+25);}if(!cyclic0(Ab,Bb))abort();int Q=0;for(int r=1;r<=24;r++){int num=corr(Ab,r)+corr(Ab,50-r)+corr(Bb,r)+corr(Bb,50-r);if(num%4)abort();int u=num/4;Q+=u*u;}if(Q>57)continue;qpass++;int exactcap=57-Q;for(int aa:units){int ah=(aa&1)?aa:aa+25,sh=(ah-1)/2;uint64_t TA=multperm(Ab,ah),TB=multperm(Bb,ah);for(int bb=0;bb<25;bb++){trans++;uint64_t X=rot50(TA,bb),Y=rot50(TB,bb+sh);bool ook=true;for(int r=24;r>=0;r--){if(abs(oddcorr(X,Y,r))!=1){ook=false;break;}}if(!ook)continue;opass++;int cap=exactcap,vs=0;for(int r=1;r<=24;r++){int num=(corr(X,r)-corr(X,50-r))+(corr(Y,r)-corr(Y,50-r));if(num%4)abort();int v=num/4;vs+=v*v;if(vs>cap)break;}if(vs<=cap){vpass++;int E=energy(X,Y);int old=best.load();while(E<old&&!best.compare_exchange_weak(old,E)){}if(E<=570){epass++;
#pragma omp critical
cout<<"TARGET rep="<<hi<<" E="<<E<<" A="<<X<<" B="<<Y<<"\n";}}}}}}
 cout<<"K21_FULLGAMMA_SUMMARY reps="<<hs.size()<<" alphas="<<alphas<<" half_gamma_solutions="<<lifts<<" full_gamma_solutions="<<(2*lifts.load())<<" Q_le_57="<<qpass<<" affine_transforms="<<trans<<" Vbudget_pass="<<vpass<<" oddperfect_pass="<<opass<<" E_le_570="<<epass<<" best="<<(best==INT_MAX?-1:best.load())<<"\n";
}
